"""Build a standalone offline review gallery preserving actual MCP responses."""
from pathlib import Path
import json, html, markdown
OUT=Path(__file__).resolve().parent
capture=json.loads((OUT/'responses.json').read_text())
notes={
 'broad': ('búsqueda','Orientarse en el sistema','La consulta recupera eventos, tabla, documentación e infraestructura; los vínculos entre repos aparecen antes que el listado de entidades.','Es una búsqueda amplia: no está restringida a HTTP y muestra solo 8 de 36 coincidencias. No demuestra que haya revisado todos los consumidores.','¿La información de docs y deployment ayuda a orientarse o desplaza las relaciones que te interesan?'),
 'http': ('http','Descubrir consumidores de un endpoint','El texto identifica dos vínculos: tests → api y web → api, con método, path y archivos de evidencia.','No contiene assertions ni el cuerpo del handler. Relación confirmada significa enlace observado, no comportamiento correcto.','Aparecen también servicios, documentación y ownership. El JSON compacto ocupa casi diez veces lo que ocupa el texto.'),
 'http-filtered': ('http','Comparar una consulta más acotada','Mismo término y misma página máxima, con node_kinds=http_operation: quedan tres entidades y los dos vínculos HTTP.','El filtro elimina otros tipos de entidad; todavía no compara valores de respuesta o assertions.','Comparar con «Vínculo HTTP»: ¿este nivel de detalle responde mejor al agente?'),
 'test-query': ('http','Encontrar el nodo que sirve de punto de partida','Localiza el test y muestra su relación validates con la operación de la API. El JSON contiene los identificadores para el siguiente paso.','No devuelve el contenido del test. El título normaliza el nombre: testcreateorder; el nombre original sigue en la relación.','¿La coincidencia con una migración y el símbolo de la API resulta útil para esta consulta tan específica?'),
 'test-context': ('http','Inspeccionar una relación concreta','Una relación semántica saliente: test del repo tests valida la operación del repo api. Incluye dos referencias de evidencia.','El path registrado del test usa python/pytest::test_create_order; el archivo real se encuentra en las referencias. No muestra la assertion.','¿Queda suficientemente claro qué nodo valida a cuál y dónde ir a leer el código?'),
 'trace': ('http','Confirmar un camino entre dos nodos','Devuelve un único salto, su dirección, los dos repositorios y las evidencias. Es la respuesta más corta de los ejemplos que confirman un enlace.','El trace confirma conexión, no una diferencia de status ni que el test pase. Ambos IDs proceden del grafo real.','¿Alcanza con la cadena y las referencias, sin volver a enumerar entidades y metadatos?'),
 'events': ('datos','Entender una integración por eventos','La primera relación expresa api publica orders.created a worker. La frase se deriva de publisher y subscriber sobre un canal exacto.','En la página hay dos entidades llamadas orders.created con distinta identidad. No se ha verificado entrega ni compatibilidad de payloads.','También aparece orders.createdat. La evidencia visible de la frase incluye API; revisar si debería mostrarse igualmente el archivo del suscriptor.'),
 'database': ('datos','Ver quién consulta una tabla de otro repo','Atribuye commerce.orders a api y conecta load_order del worker con esa tabla; las referencias incluyen ambos extremos.','Declara que omitió cuatro enlaces estructurales. No demuestra exhaustividad de accesos ni que el SQL funcione en ejecución.','¿La relación documents del README aporta a la pregunta sobre uso de la tabla o distrae?'),
 'web-explore': ('código','Explorar código y buscar un salto federado','Devuelve createOrder y el fetch POST /api/orders con líneas. El código aparece delimitado como contenido no confiable.','No hay federated_handoffs ni next_actions, aunque la consulta HTTP sí enlaza web → api. Los gaps y truncations también están vacíos.','Esta captura sugiere revisar la correlación entre el símbolo local y el nodo HTTP. No prueba por sí sola la causa de esa ausencia.'),
 'api-explore': ('código','Leer la implementación de destino','Devuelve create_order, sus callers locales y el código con líneas. El handler retorna el string created.','No expresa un status HTTP explícito. El estado efectivo requiere interpretar Axum; esta tool no resuelve sola la comparación con el test.','El código incluye también KafkaProducer y publish_order_created. ¿Es contexto útil o debería acotarse al handler?'),
 'test-explore': ('código','Leer la assertion y saltar al repo API','Muestra assert response.status_code == 201 y un handoff confirmado al nodo POST /api/orders en api.','La respuesta no afirma que el endpoint devuelva 200 ni que el PR sea incorrecto. La clasificación de una discrepancia corresponde al revisor.','Contrastar con explore de web: aquí sí aparece la navegación federada y una próxima acción.'),
 'missing': ('límites','Evitar que una búsqueda vacía se lea como prueba','Explica que query consulta entidades y contratos persistidos, no cuerpos de código, y recomienda Explore.','Cero resultados no prueba que refundInvoice no exista. El estado es degraded aunque la frescura del snapshot es fresh.','¿La explicación permite elegir una tool distinta sin llevar al agente a descartar la hipótesis?'),
 'bad-scope': ('límites','Corregir una llamada incompleta','Explica que repository es obligatorio porque el workspace tiene seis repositorios.','No ejecuta una exploración arbitraria ni elige un repo por el agente. No hay datos de resultado.','¿El mensaje de error permite corregir la llamada con suficiente claridad?')
}
for c in capture['cases']:
    group,goal,useful,limit,review=notes[c['id']]
    c.update(group=group,goal=goal,useful=useful,limit=limit,review=review)
    r=c['response'];s=r.get('structuredContent',{})
    text='\n'.join(b.get('text','') for b in r.get('content',[]))
    structured=json.dumps(s,ensure_ascii=False,separators=(',',':'))
    wire=json.dumps(r,ensure_ascii=False,separators=(',',':'))
    c.update(text=text,rendered=markdown.markdown(text,extensions=['fenced_code','tables']),text_chars=len(text),structured_chars=len(structured),wire_chars=len(wire),text_lines=len(text.splitlines()),status=s.get('status','protocol_error'),freshness=s.get('freshness',{}).get('overall','unknown'))
DATA=json.dumps(capture,ensure_ascii=False,separators=(',',':')).replace('<','\\u003c').replace('&','\\u0026')
PAGE=r'''<!doctype html>
<html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Code System Graph · Respuestas para agentes</title>
<style>
:root{color-scheme:light;--bg:#f5f6f8;--surface:#fff;--text:#182636;--muted:#556374;--border:#d8dfe8;--blue:#185bc1;--soft:#e8f0fd;--code:#f1f4f8;--good:#16704b;--warn:#945100;--shadow:0 3px 18px #172b4610}
@media(prefers-color-scheme:dark){:root{color-scheme:dark;--bg:#131b26;--surface:#1b2635;--text:#edf2f9;--muted:#b1bfd0;--border:#344457;--blue:#91b7ff;--soft:#213c61;--code:#121b28;--good:#87dbb2;--warn:#ffcd83;--shadow:none}}
*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font:16px/1.55 system-ui,-apple-system,Segoe UI,sans-serif}button,select,textarea{font:inherit}button,select{cursor:pointer}button:focus-visible,select:focus-visible,textarea:focus-visible,a:focus-visible{outline:3px solid var(--blue);outline-offset:3px}a{color:var(--blue)}header,.intro,.layout,.foot{max-width:1400px;margin:auto;padding:24px 32px}header{display:flex;gap:20px;align-items:center;justify-content:space-between;padding-bottom:0}.eyebrow{font-weight:700;color:var(--blue);font-size:13px;text-transform:uppercase;letter-spacing:.06em}h1{font-size:clamp(26px,3vw,38px);line-height:1.2;margin:8px 0}h2{font-size:24px;line-height:1.3;margin:0 0 12px}h3{font-size:17px;margin:0 0 8px}p{margin:0 0 12px}.muted{color:var(--muted)}.intro{padding-top:18px;padding-bottom:0}.provenance{display:flex;gap:10px;flex-wrap:wrap;margin:14px 0}.badge{display:inline-block;font-size:13px;padding:3px 9px;border-radius:6px;background:var(--code)}.journey{display:flex;flex-wrap:wrap;gap:12px;align-items:center;margin-top:18px;padding:12px 0;border-top:1px solid var(--border);border-bottom:1px solid var(--border)}.journey strong{color:var(--blue)}.layout{display:grid;grid-template-columns:275px minmax(0,1fr);gap:28px;align-items:start}.sidebar{position:sticky;top:18px}.filter{width:100%;padding:9px;border:1px solid var(--border);border-radius:7px;background:var(--surface);color:var(--text);margin:8px 0 12px}.cases{display:flex;flex-direction:column;gap:5px}.case{background:transparent;color:var(--text);border:1px solid transparent;border-radius:8px;padding:9px 11px;text-align:left;font-size:14px;line-height:1.4}.case span{display:block;color:var(--muted);font-size:12px;margin-top:3px}.case[aria-pressed=true]{background:var(--soft);border-color:var(--blue)}.case:hover{background:var(--code)}.case[hidden]{display:none}.sidebar-tip{font-size:13px;margin-top:18px;color:var(--muted)}.panel{background:var(--surface);border:1px solid var(--border);border-radius:12px;box-shadow:var(--shadow);padding:24px;min-width:0}.query{padding:16px;background:var(--code);border-radius:8px;margin:16px 0}.query strong{font-size:14px}.query p{margin:4px 0 10px}.query pre{margin:0;max-height:none;padding:0;background:none}.annotations{display:grid;grid-template-columns:1fr 1fr;gap:18px;margin:18px 0}.annotation{border-left:3px solid var(--border);padding-left:12px;font-size:14px}.annotation h3{font-size:14px}.observation{font-size:14px;margin-bottom:20px;padding:12px 0;border-top:1px solid var(--border);border-bottom:1px solid var(--border)}.metrics{display:grid;grid-template-columns:repeat(3,1fr);gap:16px;margin:16px 0}.metric{padding:12px 0}.metric small{display:block;color:var(--muted)}.metric b{font-size:23px;font-variant-numeric:tabular-nums}.bars{display:flex;height:9px;gap:3px;margin:5px 0 12px}.text-bar{background:var(--blue);min-width:3px}.json-bar{background:var(--muted);opacity:.6;min-width:3px}.legend{display:flex;gap:20px;font-size:12px;color:var(--muted);margin-bottom:16px}.tabs{display:flex;gap:5px;flex-wrap:wrap;border-bottom:1px solid var(--border);margin-bottom:16px}.tab{border:0;background:none;color:var(--muted);padding:10px 12px;font-size:14px;border-bottom:3px solid transparent}.tab[aria-selected=true]{color:var(--blue);border-bottom-color:var(--blue);font-weight:650}.response{max-height:620px;overflow:auto;padding:2px 14px 8px 0;min-height:220px}.response h1{font-size:23px}.response h2{font-size:19px;margin:22px 0 10px}.response h3{font-size:16px}.response p,.response li{font-size:15px}.response ul{padding-left:24px}.response li{margin-bottom:12px}code{font-family:ui-monospace,SFMono-Regular,Consolas,monospace;font-size:.9em;overflow-wrap:anywhere}pre{white-space:pre-wrap;overflow-wrap:anywhere;tab-size:2;background:var(--code);padding:14px;border-radius:6px;font-size:13px;line-height:1.55}.response pre{margin:0 0 14px}.response code{word-break:break-word}.view-note{font-size:12px;color:var(--muted);margin:10px 0}.feedback{margin-top:24px;padding-top:20px;border-top:1px solid var(--border)}.feedback label{display:block;font-size:14px;font-weight:600;margin-bottom:6px}.feedback select{max-width:360px;margin:0 0 12px}.feedback textarea{display:block;width:100%;min-height:90px;border:1px solid var(--border);border-radius:7px;padding:10px;background:var(--surface);color:var(--text);resize:vertical}.feedback-bottom{display:flex;gap:12px;flex-wrap:wrap;align-items:center;margin-top:12px}.button{padding:9px 12px;border:1px solid var(--border);border-radius:7px;color:var(--text);background:var(--surface);font-size:14px}.button.primary{background:var(--blue);color:var(--surface);border-color:var(--blue)}.feedback-bottom small{color:var(--muted)}.foot{font-size:13px;padding-top:0}.foot details{margin-top:12px}.foot summary{cursor:pointer}#source-details pre{max-height:500px;overflow:auto}#capture-details{word-break:break-word}.status{color:var(--good)}.status.degraded,.status.error{color:var(--warn)}[hidden]{display:none!important}
@media(max-width:850px){header,.intro,.layout,.foot{padding-left:18px;padding-right:18px}.layout{grid-template-columns:1fr}.sidebar{position:static}.cases{display:grid;grid-template-columns:repeat(2,minmax(0,1fr))}.sidebar-tip{margin-top:8px}.panel{padding:18px}}@media(max-width:540px){header{display:block}.annotations{grid-template-columns:1fr}.metrics{gap:6px}.metric b{font-size:19px}.cases{grid-template-columns:1fr}.response{max-height:540px}.tab{padding:9px 8px}.badge{font-size:12px}}
</style></head><body>
<header><div><div class="eyebrow">Code System Graph · evaluación de contexto</div><h1>¿Qué recibe el agente?</h1></div><span class="badge">Capturas MCP reales · fixture sintética</span></header>
<section class="intro"><p>Explora consultas, relaciones y código tal como los entrega la tool. La respuesta original está separada de <strong>mi lectura para ayudarte a evaluarla</strong>. No son respuestas idealizadas ni una maqueta de Themis.</p>
<div class="provenance" id="provenance"></div>
<p class="muted">Empieza por <strong>Vínculo HTTP</strong>, compáralo con <strong>Misma búsqueda con filtro</strong> y luego revisa los tres casos de <strong>explore</strong>. <code>confirmed</code> describe el enlace observado, no un defecto confirmado.</p>
<div class="journey" aria-label="Relaciones de ejemplo"><span><strong>web</strong> llama a <strong>api</strong></span><span>·</span><span><strong>tests</strong> valida <strong>api</strong></span><span>·</span><span><strong>api</strong> publica a <strong>worker</strong></span><span>·</span><span><strong>worker</strong> consulta tabla definida en <strong>api</strong></span></div>
</section>
<main class="layout"><aside class="sidebar"><label for="group"><strong>Ejemplos</strong></label><select class="filter" id="group"><option value="all">Todos los casos</option><option value="http">HTTP y tests</option><option value="código">Código y saltos federados</option><option value="datos">Eventos y base de datos</option><option value="búsqueda">Búsqueda amplia</option><option value="límites">Límites y errores</option></select><nav class="cases" id="cases" aria-label="Seleccionar consulta"></nav><p class="sidebar-tip">Los caracteres son medidas exactas; no son tokens. Texto y JSON son dos canales de la misma respuesta. El host decide cuáles envía al modelo.</p></aside>
<article class="panel"><div class="eyebrow" id="kind"></div><h2 id="title"></h2><p id="goal" class="muted"></p><div id="status"></div>
<div class="query"><strong>Pregunta que motiva la consulta</strong><p id="question"></p><details><summary>Llamada exacta a la tool</summary><pre><code id="request"></code></pre></details></div>
<div class="metrics" aria-label="Tamaño de respuesta"><div class="metric"><small>Texto original</small><b id="text-size"></b><small>caracteres</small></div><div class="metric"><small>JSON estructurado compacto</small><b id="json-size"></b><small>caracteres</small></div><div class="metric"><small>Si el host envía ambos</small><b id="both-size"></b><small>suma de caracteres de contenido</small></div></div>
<div class="bars" aria-hidden="true"><div class="text-bar" id="text-bar"></div><div class="json-bar" id="json-bar"></div></div><div class="legend"><span>Azul: texto</span><span>Gris: JSON estructurado</span></div>
<div class="tabs" role="tablist" aria-label="Canal de respuesta"><button class="tab" id="tab-readable" role="tab" aria-controls="response" data-view="readable" aria-selected="true">Texto legible</button><button class="tab" id="tab-text" role="tab" aria-controls="response" data-view="text" aria-selected="false">Texto literal</button><button class="tab" id="tab-json" role="tab" aria-controls="response" data-view="json" aria-selected="false">JSON estructurado</button><button class="tab" id="tab-wire" role="tab" aria-controls="response" data-view="wire" aria-selected="false">Respuesta MCP completa</button></div>
<div id="response" class="response" role="tabpanel" aria-labelledby="tab-readable" tabindex="0"></div><p id="view-note" class="view-note"></p>
<details style="margin-top:20px"><summary><strong>Mi lectura: utilidad y puntos para revisar</strong></summary><section class="annotations" aria-label="Lectura editorial separada"><div class="annotation"><h3>Qué aporta · mi lectura</h3><p id="useful"></p></div><div class="annotation"><h3>Qué no permite concluir · mi lectura</h3><p id="limit"></p></div></section><p class="observation"><strong>Punto para evaluar: </strong><span id="review"></span></p>
</details>
<section class="feedback"><h3>Tu evaluación de este caso</h3><label for="rating">¿Qué tan útil resulta?</label><select class="filter" id="rating"><option value="">Sin evaluar</option><option>Útil y claro</option><option>Útil, pero con ruido</option><option>Falta contexto o evidencia</option><option>No responde a la consulta</option></select><label for="notes">Qué conservar, quitar o mejorar</label><textarea id="notes" placeholder="Por ejemplo: conservar las evidencias de ambos extremos, quitar coincidencias de documentación…"></textarea><div class="feedback-bottom"><button class="button primary" id="export">Descargar mis observaciones</button><button class="button" id="previous">Anterior</button><button class="button" id="next">Siguiente</button><small id="saved">Se guarda en este navegador. No se envía a ningún servidor.</small></div></section>
</article></main>
<footer class="foot"><p>El HTML funciona sin conexión. No ejecuta consultas nuevas: permite examinar una captura reproducible. Los ejemplos no certifican cobertura de repositorios reales ni una integración ya implementada en Themis.</p>
<details><summary>Entorno y procedencia de las capturas</summary><div id="capture-details"></div></details>
<details id="source-details"><summary>Código original de la fixture para contrastar las respuestas</summary><div id="sources"></div></details>
</footer>
<script id="capture-data" type="application/json">__DATA__</script>
<script>
(()=>{'use strict';const data=JSON.parse(document.getElementById('capture-data').textContent);const cases=data.cases;const $=id=>document.getElementById(id);const fmt=n=>new Intl.NumberFormat('es-UY').format(n);let current=cases.find(c=>c.id==='http');let view='readable';let group='all';let ratings={};let canStore=true;const storeKey='csgraph-response-review-'+data.source_commit;
try{ratings=JSON.parse(localStorage.getItem(storeKey)||'{}')}catch{canStore=false}
const esc=s=>String(s).replace(/[&<>"']/g,x=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[x]));
$('provenance').innerHTML=[data.binary,'CodeGraph '+data.codegraph,cases.length+' respuestas','snapshot local · 6 repos'].map(t=>'<span class="badge">'+esc(t)+'</span>').join('');
$('capture-details').innerHTML='<p>Captura: '+esc(data.captured_at)+'<br>Fuente: commit <code>'+esc(data.source_commit)+'</code><br>'+esc(data.origin)+'</p><p>Binario compilado localmente desde ese commit; no se está usando el csgraph 1.0.2 que estaba en PATH. Las consultas explore usan CodeGraph real, sin fake provider.</p><p>Los IDs de test, endpoint y tabla se seleccionaron del grafo exportado; no se inventaron. Cada carpeta de la fixture se inicializó como repositorio Git sintético en rama <code>example</code>.</p><pre>'+esc(JSON.stringify(data.repo_revisions,null,2))+'</pre><p>Reproducir: ejecutar <code>capture.py</code> y <code>build_html.py</code> junto a este archivo. Las rutas de binarios del capturador corresponden a este entorno.</p>';
$('sources').innerHTML=Object.entries(data.sources).map(([name,source])=>'<h3>'+esc(name)+'</h3><pre>'+esc(source.split('\n').map((s,i)=>(i+1)+'\t'+s).join('\n'))+'</pre>').join('');
const ordered=cases.filter(c=>c.group==='http').concat(cases.filter(c=>c.group==='código'),cases.filter(c=>c.group==='datos'),cases.filter(c=>c.group==='búsqueda'),cases.filter(c=>c.group==='límites'));
$('cases').innerHTML=ordered.map(c=>'<button type="button" class="case" data-id="'+esc(c.id)+'" aria-pressed="false">'+esc(c.title)+'<span>'+esc(c.tool)+' · '+fmt(c.text_chars)+' caracteres de texto</span></button>').join('');
function renderResponse(){document.querySelectorAll('.tab').forEach(b=>b.setAttribute('aria-selected',String(b.dataset.view===view)));$('response').setAttribute('aria-labelledby','tab-'+view);if(view==='readable'){$('response').innerHTML=current.rendered;$('view-note').textContent='Markdown original renderizado. No se ha resumido ni recortado; desplázate dentro de la respuesta si es larga.'}else{const text=view==='text'?current.text:JSON.stringify(view==='json'?current.response.structuredContent:current.response,null,2);$('response').innerHTML='<pre><code>'+esc(text)+'</code></pre>';$('view-note').textContent=view==='text'?'Valor literal de content[].text, completo.':view==='json'?'structuredContent íntegro. Se muestra con indentación; la métrica usa JSON compacto sin espacios de presentación.':'CallToolResult íntegro: content y structuredContent. El envoltorio JSON agrega sintaxis y escapes a la suma mostrada arriba.'}$('response').scrollTop=0}
function show(c){current=c;for(const id of ['title','goal','question','useful','limit','review'])$(id).textContent=c[id];$('kind').textContent=c.tool+' · '+c.group;$('request').textContent=JSON.stringify({name:c.tool,arguments:c.arguments},null,2);$('status').innerHTML='<span class="badge status '+esc(c.status)+'">Estado: '+esc(c.status)+'</span> <span class="badge">Frescura: '+esc(c.freshness)+'</span> <span class="badge">'+c.text_lines+' líneas de texto</span>';$('text-size').textContent=fmt(c.text_chars);$('json-size').textContent=fmt(c.structured_chars);$('both-size').textContent=fmt(c.text_chars+c.structured_chars);const sum=c.text_chars+c.structured_chars;$('text-bar').style.width=(100*c.text_chars/sum)+'%';$('json-bar').style.width=(100*c.structured_chars/sum)+'%';document.querySelectorAll('.case').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.id===c.id)));$('rating').value=ratings[c.id]?.rating||'';$('notes').value=ratings[c.id]?.notes||'';renderResponse()}
function visible(){return ordered.filter(c=>group==='all'||c.group===group)}
$('cases').addEventListener('click',e=>{const b=e.target.closest('button[data-id]');if(b)show(cases.find(c=>c.id===b.dataset.id))});document.querySelectorAll('.tab').forEach(b=>b.addEventListener('click',()=>{view=b.dataset.view;renderResponse()}));
$('group').addEventListener('change',()=>{group=$('group').value;document.querySelectorAll('.case').forEach(b=>b.hidden=!visible().some(c=>c.id===b.dataset.id));if(!visible().includes(current))show(visible()[0])});
function save(){ratings[current.id]={rating:$('rating').value,notes:$('notes').value};try{localStorage.setItem(storeKey,JSON.stringify(ratings));$('saved').textContent='Guardado localmente. No se envía a ningún servidor.'}catch{canStore=false;$('saved').textContent='El navegador no permite guardar; descarga tus observaciones antes de cerrar.'}}
$('rating').addEventListener('change',save);$('notes').addEventListener('input',save);
$('export').addEventListener('click',()=>{const output={source_commit:data.source_commit,captured_at:data.captured_at,observations:cases.filter(c=>ratings[c.id]?.rating||ratings[c.id]?.notes).map(c=>({id:c.id,title:c.title,tool:c.tool,arguments:c.arguments,...ratings[c.id]}))};const url=URL.createObjectURL(new Blob([JSON.stringify(output,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='observaciones-code-system-graph.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)});
for(const [id,direction] of [['previous',-1],['next',1]])$(id).addEventListener('click',()=>{const list=visible();const index=list.indexOf(current);show(list[(index+direction+list.length)%list.length])});
const params=new URLSearchParams(location.search);if(params.get('case'))current=cases.find(c=>c.id===params.get('case'))||current;if(['readable','text','json','wire'].includes(params.get('view')))view=params.get('view');show(current);if(!canStore)$('saved').textContent='No hay almacenamiento local disponible. Puedes descargar tus observaciones.';
})();
</script></body></html>'''
(OUT/'index.html').write_text(PAGE.replace('__DATA__',DATA))
print('HTML written:',OUT/'index.html', 'bytes:',(OUT/'index.html').stat().st_size)
